/**
 * Generates the TypeScript types in src/types/ from the JSON Schemas in schema/, so a schema is
 * the single source of truth for its data shape and the site and the validators cannot disagree
 * about it.
 *
 *   npm run types          write the generated files
 *   npm run types:check    fail if a committed file is stale
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import { compile, type JSONSchema } from "json-schema-to-typescript";

import { ROOT, isEntryPoint, runMain } from "../src/paths.ts";

export const TARGETS = [
  { schema: "schema/edition.schema.json", output: "src/types/edition.ts" },
  { schema: "schema/territories.schema.json", output: "src/types/territories.ts" },
  { schema: "schema/research-brief.schema.json", output: "src/types/research-brief.ts" },
  { schema: "schema/tls-intermediates.schema.json", output: "src/types/tls-intermediates.ts" },
  { schema: "schema/source-terms.schema.json", output: "src/types/source-terms.ts" },
] as const;

const BANNER = "/* Generated by scripts/generate-types.ts from the JSON Schema. Do not edit; run `npm run types`. */";

/**
 * A definition that carries both properties and an `allOf` comes out of json-schema-to-typescript
 * as an alias plus a numbered interface. This schema produces two shapes, and both read badly:
 *
 *     export type ContactPoint = ContactPoint1;              // the allOf only adds conditions
 *     export type EuSnapshot = SnapshotBase & EuSnapshot1;   // shared body plus own identity
 *
 * The first is collapsed into one `interface ContactPoint`, keeping the alias's description. In the
 * second the intersection is the point, so only the numbered half is renamed to `<Kind>Identity`.
 */
export function normalizeGeneratedNames(content: string): string {
  let result = content;
  for (const match of content.matchAll(/(\/\*\*(?:(?!\*\/)[\s\S])*\*\/\n)?export type (\w+) = \2 ?1;\n/g)) {
    const [alias, comment = "", name = ""] = match;
    result = result
      .replace(alias, "")
      .replace(`export interface ${name}1 {`, `${comment}export interface ${name} {`)
      .replaceAll(new RegExp(`\\b${name}1\\b`, "g"), name);
  }
  return result.replaceAll(/\b(\w+)Snapshot1\b/g, "$1Identity");
}

export async function renderTypes(): Promise<Array<{ output: string; content: string }>> {
  return Promise.all(
    TARGETS.map(async ({ schema, output }) => {
      // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- schema files are repository content, not external input
      const document = JSON.parse(readFileSync(path.join(ROOT, schema), "utf8")) as JSONSchema;
      const content = await compile(document, document.title ?? path.basename(schema), {
        bannerComment: BANNER,
        additionalProperties: false,
        unreachableDefinitions: false,
        style: { singleQuote: false, printWidth: 120 },
      });
      return { output, content: normalizeGeneratedNames(content) };
    }),
  );
}

if (isEntryPoint(import.meta.url)) {
  runMain(async () => {
    const checkOnly = process.argv.includes("--check");
    const stale: string[] = [];
    for (const { output, content } of await renderTypes()) {
      const file = path.join(ROOT, output);
      const current = existsSync(file) ? readFileSync(file, "utf8") : "";
      if (current === content) continue;
      if (checkOnly) {
        stale.push(output);
      } else {
        writeFileSync(file, content);
        console.log(`wrote ${output}`);
      }
    }
    if (stale.length) {
      console.error(`stale generated types: ${stale.join(", ")} — run \`npm run types\``);
      return 1;
    }
    if (checkOnly) console.log("generated types are up to date");
    return 0;
  });
}
